/* QuickRN original NCLEX beta expansion. QR-001340–QR-001369.
 * All items are drafts pending qualified nurse-educator review.
 * Additive loader shared by all four exam modes.
 */
(function(root){
'use strict';
const bank=Array.isArray(root.questions)?root.questions:(typeof questions!=='undefined'?questions:[]);
if(!Array.isArray(root.questions))root.questions=bank;
const items=[
{id:'QR-001340',type:'Single Choice',category:'Management of Care',topic:'Delegation',title:'Which task is appropriate for an RN to delegate to an experienced UAP?',options:['Assess new chest pain','Obtain routine vital signs for a stable client','Teach incentive spirometer use','Evaluate opioid response'],correctAnswer:'Obtain routine vital signs for a stable client',rationale:'Routine data collection for a stable client may be delegated. Assessment, teaching, and evaluation remain RN responsibilities.',difficulty:'Moderate'},
{id:'QR-001341',type:'Single Choice',category:'Safety and Infection Control',topic:'Central-line care',title:'Which action reduces infection risk during a central-line dressing change?',options:['Use clean gloves only','Perform hand hygiene and use sterile technique','Apply ointment routinely','Leave the site uncovered'],correctAnswer:'Perform hand hygiene and use sterile technique',rationale:'Hand hygiene and aseptic technique reduce contamination during central-line dressing changes.',difficulty:'Moderate'},
{id:'QR-001342',type:'Single Choice',category:'Pharmacological and Parenteral Therapies',topic:'Type 1 diabetes while NPO',title:'A client with type 1 diabetes is NPO for a procedure. Which action is appropriate regarding insulin?',options:['Omit all insulin','Clarify the regimen; basal insulin is generally still needed','Give the full prandial dose','Replace insulin with oral glucose'],correctAnswer:'Clarify the regimen; basal insulin is generally still needed',rationale:'Basal insulin is generally required in type 1 diabetes to prevent ketosis. Prandial dosing is adjusted when meals are withheld.',difficulty:'High'},
{id:'QR-001343',type:'Single Choice',category:'Reduction of Risk Potential',topic:'Pulmonary embolism',title:'A postoperative client develops sudden dyspnea, pleuritic chest pain, HR 124/min, and SpO₂ 88%. What is the priority?',options:['Encourage ambulation','Apply oxygen and activate urgent assessment','Give a stool softener','Reassess in 1 hour'],correctAnswer:'Apply oxygen and activate urgent assessment',rationale:'Sudden dyspnea, pleuritic pain, tachycardia, and hypoxemia may indicate pulmonary embolism and require emergency evaluation.',difficulty:'High'},
{id:'QR-001344',type:'Single Choice',category:'Physiological Adaptation',topic:'Acute stroke',title:'Which information is essential when evaluating a client for acute stroke reperfusion therapy?',options:['Last-known-well time','Usual bedtime','Last bowel movement','Preferred pharmacy'],correctAnswer:'Last-known-well time',rationale:'The last-known-well time anchors the treatment window for acute stroke interventions.',difficulty:'High'},
{id:'QR-001345',type:'Single Choice',category:'Health Promotion and Maintenance',topic:'Immunization',title:'Which vaccine is generally contraindicated in a client with severe immunosuppression?',options:['Inactivated influenza','Hepatitis B','Live attenuated MMR','Pneumococcal conjugate'],correctAnswer:'Live attenuated MMR',rationale:'Live vaccines are generally contraindicated in severe immunosuppression; an individualized immunization plan is needed.',difficulty:'Moderate'},
{id:'QR-001346',type:'Single Choice',category:'Psychosocial Integrity',topic:'Therapeutic communication',title:'A client with cancer says, “I am terrified I will not see my children grow up.” Which response is therapeutic?',options:['Stay positive','Tell me more about what worries you most','Many people live for years','Be strong for your children'],correctAnswer:'Tell me more about what worries you most',rationale:'An open-ended response acknowledges fear and invites the client to express concerns without false reassurance.',difficulty:'Moderate'},
{id:'QR-001347',type:'Single Choice',category:'Basic Care and Comfort',topic:'Dysphagia',title:'Which action supports safer feeding for a client with dysphagia?',options:['Place food on the weaker side','Position upright and offer small amounts slowly','Encourage talking while chewing','Offer thin liquids'],correctAnswer:'Position upright and offer small amounts slowly',rationale:'Upright positioning, small bites, and a slow pace support safer swallowing. Follow the prescribed food and liquid consistency.',difficulty:'Moderate'},
{id:'QR-001348',type:'Single Choice',category:'Physiological Adaptation',topic:'COPD and ABGs',title:'A client with COPD is drowsy. ABGs: pH 7.28, PaCO₂ 68 mm Hg, HCO₃⁻ 30 mEq/L. How are these results interpreted?',options:['Respiratory acidosis with partial compensation','Metabolic alkalosis','Respiratory alkalosis','Fully compensated metabolic acidosis'],correctAnswer:'Respiratory acidosis with partial compensation',rationale:'Low pH and elevated PaCO₂ indicate respiratory acidosis; elevated bicarbonate reflects partial renal compensation.',difficulty:'High'},
{id:'QR-001349',type:'Single Choice',category:'Pharmacological and Parenteral Therapies',topic:'Vancomycin infusion reaction',title:'During IV vancomycin infusion, a client develops facial flushing and itching. What should the nurse do first?',options:['Increase the rate','Pause the infusion and assess the client','Give the next dose early','Document as therapeutic effect'],correctAnswer:'Pause the infusion and assess the client',rationale:'Flushing and pruritus may occur with rapid infusion. Pause, assess for hypotension or airway symptoms, and notify the prescriber.',difficulty:'Moderate'},
{id:'QR-001350',type:'Single Choice',category:'Management of Care',topic:'Prioritization',title:'Which client should the nurse assess first?',options:['Client with chronic arthritis requesting analgesia','Client 2 hours after thyroidectomy with stridor','Client with glucose 198 mg/dL','Client awaiting discharge teaching'],correctAnswer:'Client 2 hours after thyroidectomy with stridor',rationale:'Stridor after thyroidectomy may indicate airway obstruction from edema or hematoma and is an immediate emergency.',difficulty:'High'},
{id:'QR-001351',type:'Single Choice',category:'Safety and Infection Control',topic:'Clostridioides difficile',title:'Which hand hygiene method is preferred after caring for a client with C. difficile?',options:['Alcohol rub only','Soap and water','Sterile water only','Gloves instead of hand hygiene'],correctAnswer:'Soap and water',rationale:'Soap and water physically remove spores and are preferred after C. difficile care, in addition to contact precautions.',difficulty:'Moderate'},
{id:'QR-001352',type:'Single Choice',category:'Physiological Adaptation',topic:'Acute pancreatitis',title:'Which intervention should the nurse anticipate during initial management of acute pancreatitis?',options:['High-fat meals','IV fluids and analgesia with monitoring','Unrestricted oral intake immediately','Routine laxatives'],correctAnswer:'IV fluids and analgesia with monitoring',rationale:'Initial management commonly includes fluid support, analgesia, monitoring for complications, and nutrition planning based on clinical status.',difficulty:'Moderate'},
{id:'QR-001353',type:'Single Choice',category:'Maternal Newborn',topic:'Neonatal hypoglycemia',title:'A newborn of a diabetic parent is jittery with a bedside glucose of 32 mg/dL. What is the priority?',options:['Recheck in 6 hours','Initiate the neonatal hypoglycemia protocol promptly','Give sterile water','Delay feeding'],correctAnswer:'Initiate the neonatal hypoglycemia protocol promptly',rationale:'Jitteriness with low glucose requires prompt intervention under the neonatal protocol, based on symptoms and local thresholds.',difficulty:'High'},
{id:'QR-001354',type:'Single Choice',category:'Child Health',topic:'Croup',title:'A 2-year-old with croup has stridor at rest and marked retractions. Which treatment should the nurse anticipate?',options:['Throat culture before treatment','Nebulized epinephrine and corticosteroid','Cough suppressant and discharge','Encourage crying'],correctAnswer:'Nebulized epinephrine and corticosteroid',rationale:'Stridor at rest and retractions indicate significant upper-airway obstruction; nebulized epinephrine and corticosteroids are commonly indicated.',difficulty:'High'},
{id:'QR-001355',type:'Single Choice',category:'Psychosocial Integrity',topic:'Panic attack',title:'A client having a panic attack is hyperventilating. Which nursing action is best?',options:['Leave the client alone','Stay with the client and use short calm statements','Ask the client to analyze the cause','Provide detailed teaching'],correctAnswer:'Stay with the client and use short calm statements',rationale:'A calm presence, simple directions, and reduced stimulation help during acute panic. Teaching is more effective after symptoms subside.',difficulty:'Moderate'},
{id:'QR-001356',type:'Single Choice',category:'Basic Care and Comfort',topic:'Pressure injury',title:'A bedbound client has intact skin with persistent nonblanchable redness over the sacrum. How is this classified?',options:['Stage 1 pressure injury','Stage 2 pressure injury','Deep tissue pressure injury','Unstageable'],correctAnswer:'Stage 1 pressure injury',rationale:'Intact skin with localized nonblanchable erythema is consistent with a Stage 1 pressure injury.',difficulty:'Moderate'},
{id:'QR-001357',type:'Single Choice',category:'Reduction of Risk Potential',topic:'Chest tube disconnection',title:'A chest tube disconnects from the drainage system. What should the nurse do immediately?',options:['Clamp and leave clamped','Place tube end in sterile water while obtaining a new system','Remove the tube','Tape tubing to gown'],correctAnswer:'Place tube end in sterile water while obtaining a new system',rationale:'Temporarily placing the tube end in sterile water creates a water seal while a new drainage system is obtained. Follow facility protocol and assess respiratory status.',difficulty:'High'},
{id:'QR-001358',type:'Single Choice',category:'Physiological Adaptation',topic:'Thyroid storm',title:'A client with hyperthyroidism develops temperature 40 °C, severe tachycardia, agitation, and vomiting. Which complication is suspected?',options:['Myxedema coma','Thyroid storm','Addisonian crisis','SIADH'],correctAnswer:'Thyroid storm',rationale:'High fever, marked tachycardia, GI symptoms, and altered mental status in hyperthyroidism suggest a life-threatening thyroid storm.',difficulty:'High'},
{id:'QR-001359',type:'Single Choice',category:'Pharmacological and Parenteral Therapies',topic:'IV potassium',title:'Which action is essential when administering IV potassium chloride?',options:['Administer by IV push','Use an infusion pump; never give undiluted by IV push','Give undiluted through any line','Avoid monitoring'],correctAnswer:'Use an infusion pump; never give undiluted by IV push',rationale:'IV potassium must be diluted and infused at a controlled rate; IV push administration can cause fatal dysrhythmias.',difficulty:'High'},
{id:'QR-001360',type:'Single Choice',category:'Management of Care',topic:'Informed consent',title:'A client says they signed the surgical consent but do not understand the risks. What should the nurse do?',options:['Explain all risks independently','Notify the procedural provider that further explanation is needed','Witness the signature again','Tell the client the decision is final'],correctAnswer:'Notify the procedural provider that further explanation is needed',rationale:'The provider performing the procedure explains risks, benefits, and alternatives. The nurse facilitates clarification before consent proceeds.',difficulty:'Moderate'},
{id:'QR-001361',type:'Single Choice',category:'Health Promotion and Maintenance',topic:'Preeclampsia teaching',title:'Which symptom should a pregnant client at 30 weeks report immediately?',options:['Mild fatigue','Severe persistent headache with visual changes','Fetal hiccups','Increased appetite'],correctAnswer:'Severe persistent headache with visual changes',rationale:'Severe headache and visual disturbances can signal severe features of preeclampsia and require urgent evaluation.',difficulty:'High'},
{id:'QR-001362',type:'Single Choice',category:'Basic Care and Comfort',topic:'Ostomy assessment',title:'During pouch change, a colostomy stoma is moist and pink-red. How should the nurse interpret this?',options:['Expected healthy appearance','Tissue necrosis','Severe dehydration','Intestinal obstruction'],correctAnswer:'Expected healthy appearance',rationale:'A healthy stoma is typically moist and pink to red. Dusky, pale, brown, or black tissue requires prompt assessment.',difficulty:'Easy'},
{id:'QR-001363',type:'Single Choice',category:'Psychosocial Integrity',topic:'Acute delirium',title:'An older inpatient becomes acutely disoriented and tries to climb out of bed. What should the nurse do first?',options:['Assume baseline dementia','Assess reversible causes such as hypoxia, infection, pain, and medications','Apply restraints immediately','Isolate the client'],correctAnswer:'Assess reversible causes such as hypoxia, infection, pain, and medications',rationale:'Acute confusion suggests delirium. Assess oxygenation, vital signs, medications, infection, pain, and metabolic causes while maintaining safety.',difficulty:'High'},
{id:'QR-001364',type:'Single Choice',category:'Physiological Adaptation',topic:'Hyperkalemia',title:'A client with CKD has potassium 6.4 mEq/L and peaked T waves. What is the priority?',options:['Offer high-potassium food','Initiate cardiac monitoring and urgently notify the provider','Encourage ambulation','Repeat labs next week'],correctAnswer:'Initiate cardiac monitoring and urgently notify the provider',rationale:'Hyperkalemia with ECG changes creates immediate risk of lethal dysrhythmia and requires urgent treatment.',difficulty:'High'},
{id:'QR-001365',type:'Single Choice',category:'Pharmacological and Parenteral Therapies',topic:'Heparin safety',title:'A client on unfractionated heparin has a supratherapeutic aPTT and bleeding at the IV site. What should the nurse do?',options:['Increase the rate','Follow protocol to hold or adjust infusion and notify provider','Give aspirin','Ignore bleeding'],correctAnswer:'Follow protocol to hold or adjust infusion and notify provider',rationale:'Supratherapeutic anticoagulation with bleeding requires prompt action under the heparin protocol, assessment, and provider notification.',difficulty:'High'},
{id:'QR-001366',type:'Single Choice',category:'Safety and Infection Control',topic:'Neutropenic fever',title:'A chemotherapy client has ANC 400/mm³ and temperature 38.3 °C. What is the priority?',options:['Give acetaminophen and reassess tomorrow','Initiate urgent neutropenic-fever evaluation','Place fresh flowers in room','Obtain rectal temperature'],correctAnswer:'Initiate urgent neutropenic-fever evaluation',rationale:'Fever with severe neutropenia is an oncologic emergency. Prompt cultures and empiric antibiotics are time-sensitive; avoid rectal procedures.',difficulty:'High'},
{id:'QR-001367',type:'Single Choice',category:'Reduction of Risk Potential',topic:'Digoxin administration',title:'Before digoxin, the nurse obtains an adult apical pulse of 52/min. What should the nurse do?',options:['Administer with food','Withhold according to hold parameters and notify provider','Give an extra dose','Recheck after administration'],correctAnswer:'Withhold according to hold parameters and notify provider',rationale:'A low apical pulse may indicate clinically significant bradycardia. Follow ordered hold parameters and notify the prescriber.',difficulty:'Moderate'},
{id:'QR-001368',type:'Single Choice',category:'Physiological Adaptation',topic:'Anaphylaxis',title:'Minutes after an antibiotic, a client develops urticaria, wheezing, and hypotension. Which medication is priority?',options:['IM epinephrine','Oral diphenhydramine alone','IV furosemide','Acetaminophen'],correctAnswer:'IM epinephrine',rationale:'Intramuscular epinephrine is first-line treatment for anaphylaxis. Support airway and circulation and activate emergency response.',difficulty:'High'},
{id:'QR-001369',type:'Multiple Response',ngnType:'Multiple Response',category:'Pharmacological and Parenteral Therapies',topic:'Hypoglycemia recognition',title:'A client receiving insulin becomes diaphoretic and confused. Which findings support hypoglycemia? Select all that apply.',options:['Tremor','Capillary glucose 52 mg/dL','Cool clammy skin','Polyuria over several weeks','Sudden difficulty concentrating'],correctAnswers:['Tremor','Capillary glucose 52 mg/dL','Cool clammy skin','Sudden difficulty concentrating'],rationale:'Adrenergic symptoms include tremor and diaphoresis; neuroglycopenia can cause confusion and impaired concentration. A glucose of 52 mg/dL confirms hypoglycemia.',difficulty:'Moderate'}
];
const known=new Set(bank.map(q=>q&&q.id).filter(Boolean).map(String));
let added=0;items.forEach(q=>{q.source='QuickRN original beta draft';q.reviewStatus='pending_nurse_educator_review';if(!known.has(q.id)){bank.push(q);known.add(q.id);added++;}});
root.quickRNExpansionBatch20261104={authored:items.length,added,firstId:'QR-001340',lastId:'QR-001369',reviewStatus:'pending_nurse_educator_review'};
})(typeof window!=='undefined'?window:globalThis);

/* ===== END questions-bank-expansion-2026-11-04.js ===== */

